#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct Edge { int v, w, rev; };
class FlowGraph {
public:
    vector<vector<Edge>> adj;
    vector<int> lv, it;
    int s, t;
    FlowGraph(int n, int S, int T): adj(n), lv(n), it(n), s(S), t(T) {}
    void add_edge(int u, int v, int c) {
        int a = adj[v].size();
        int b = adj[u].size();
        adj[u].push_back({v, c, a});
        adj[v].push_back({u, 0, b});
    }
    bool bfs() {
        fill(lv.begin(), lv.end(), -1);
        lv[s] = 0;
        queue<int> q; q.push(s);
        while(!q.empty()) {
            int u = q.front(); q.pop();
            for(auto &e: adj[u]) {
                if(lv[e.v] == -1 && e.w > 0) {
                    lv[e.v] = lv[u] + 1;
                    q.push(e.v);
                }
            }
        }
        return lv[t] != -1;
    }
    int dfs(int u, int f) {
        if(u == t) return f;
        for(int &i = it[u]; i < (int)adj[u].size(); ++i) {
            auto &e = adj[u][i];
            if(lv[e.v] == lv[u] + 1 && e.w > 0) {
                int ret = dfs(e.v, min(f, e.w));
                if(ret) {
                    e.w -= ret;
                    adj[e.v][e.rev].w += ret;
                    return ret;
                }
            }
        }
        return 0;
    }
    ll dinic() {
        ll ans = 0;
        while(bfs()) {
            fill(it.begin(), it.end(), 0);
            while(int f = dfs(s, 2e9)) ans += f;
        }
        return ans;
    }
};
int N, K;
string A[15], B[15];
int D[15][15];
int si, sj;
int moveX[] = {1, -1, 0, 0};
int moveY[] = {0, 0, 1, -1};
void fillDist() {
    queue<pair<int,int>> q;
    q.push({si, sj});
    D[si][sj] = 1;
    int level = 1;
    while(q.size()) {
        int sz = q.size();
        for(int z=0; z<sz; ++z) {
            auto p = q.front(); q.pop();
            for(int dir=0; dir<4; ++dir) {
                int ni = p.first + moveX[dir];
                int nj = p.second + moveY[dir];
                if(ni < 0 || ni >= N || nj < 0 || nj >= N) continue;
                if(D[ni][nj] != 0 || A[ni][nj] == 'Y') continue;
                D[ni][nj] = level;
                q.push({ni,nj});
            }
        }
        ++level;
        level = min(level, K);
    }
}
int id[15][15][65];
int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> N >> K;
    for(int i=0; i<N; ++i) {
        cin >> A[i];
        for(int j=0; j<N; ++j) if(A[i][j] == 'Z') { si = i; sj = j; }
    }
    getline(cin, A[N]);
    getline(cin, A[N]);
    for(int i=0; i<N; ++i) cin >> B[i];
    fillDist();
    int cnt = 0;
    for(int i=0; i<N; ++i)
        for(int j=0; j<N; ++j) {
            if(A[i][j] >= '0' && A[i][j] <= '9') {
                if(D[i][j] == 0) D[i][j] = K;
                for(int t=0; t<D[i][j]; ++t) id[i][j][t] = ++cnt;
            }
            if(B[i][j] >= '1' && B[i][j] <= '9') id[i][j][D[i][j]] = ++cnt;
        }
    int INF = 1000000000;
    int S = 0, E = cnt + 3;
    FlowGraph fg(cnt + 5, S, E);
    for(int i=0; i<N; ++i)
        for(int j=0; j<N; ++j) {
            if(A[i][j] >= '1' && A[i][j] <= '9') fg.add_edge(S, id[i][j][0], A[i][j]-'0');
            for(int d=0; d<4; ++d) {
                int ni = i + moveX[d];
                int nj = j + moveY[d];
                if(ni < 0 || ni >= N || nj < 0 || nj >= N) continue;
                if(A[ni][nj] == 'Y' || A[ni][nj] == 'Z') continue;
                for(int t=0; ; ++t) {
                    if(id[i][j][t] == 0) break;
                    if(t == D[i][j] && B[i][j] >= '1' && B[i][j] <= '9') break;
                    if(id[ni][nj][t+1]) fg.add_edge(id[i][j][t], id[ni][nj][t+1], INF);
                }
            }
            if(B[i][j] >= '1' && B[i][j] <= '9') {
                for(int t=0; t<D[i][j]; ++t) fg.add_edge(id[i][j][t], id[i][j][t+1], INF);
                fg.add_edge(id[i][j][D[i][j]], E, B[i][j]-'0');
            }
        }
    cout << fg.dinic() << '\n';
    return 0;
}
